package servers_test

// L755A (THROWAWAY ab/l755a-diag-20261114, not for merge): the one registry column the L755A dispatch adds (servers/l755a_arms.go, generated by l755a-gen.py). The expectations are stated
// here, not derived from the code under test; the pin comes from servers/celeris/go.mod.

import (
	"os"
	"regexp"
	"testing"

	"github.com/goceleris/probatorium/servers"
)

func TestL755AStdH1ControlColumn(t *testing.T) {
	a, ok := servers.Registry["l755a-std-h1"]
	if !ok {
		t.Fatal("l755a-std-h1 is not in the registry")
	}
	base := servers.Registry["celeris-std-h1"]
	mod, err := os.ReadFile("celeris/go.mod")
	if err != nil {
		t.Fatal(err)
	}
	m := regexp.MustCompile(`(?m)^\s*github\.com/goceleris/celeris (v\S+)\s*$`).FindSubmatch(mod)
	if m == nil {
		t.Fatal("no celeris require in servers/celeris/go.mod")
	}
	if a.FrameworkVersion != string(m[1]) || a.Framework != "celeris-l755a" {
		t.Errorf("framework %s version %s, want celeris-l755a / %s (go.mod)", a.Framework, a.FrameworkVersion, m[1])
	}
	gb, isGo := a.Bin.(servers.GoBinary)
	if !isGo || gb.ModuleDir != "servers/celeris" {
		t.Errorf("bin %#v, want the servers/celeris module", a.Bin)
	}
	if a.Engine != "std-h1" || a.Engine != base.Engine || a.Capabilities != base.Capabilities || a.Category != base.Category || a.Language != base.Language {
		t.Errorf("column differs from celeris-std-h1 in engine / capabilities / category / language")
	}
	if len(a.SUTEnv) != 0 {
		t.Errorf("SUTEnv %v, want empty (as celeris-std-h1 in LF-2)", a.SUTEnv)
	}
	p, ok := a.RatedPlans["ws-echo"]
	if !ok || len(a.RatedPlans) != 1 || len(p.Fractions) != 0 || len(p.AbsoluteRPS) != 1 || p.AbsoluteRPS[0] != 60000 || p.Placeholder || p.SaturationOnly {
		t.Errorf("rated plans %#v, want exactly ws-echo: no fractions, one absolute pass at 60000", a.RatedPlans)
	}
	if a.Baseline {
		t.Errorf("Baseline is set: the column would be hidden unless BENCH_BASELINE")
	}
}
